script:
if not doc.flags.get("hr_notify_sent"):
    doc.flags.hr_notify_sent = True

    user_roles = frappe.db.sql("""
        SELECT role FROM `tabHas Role`
        WHERE parent = %s
    """, frappe.session.user, as_dict=True)

    user_roles = [r.role for r in user_roles]

    if "Employee" in user_roles and "HR Manager" not in user_roles and "HR User" not in user_roles:
        changed_fields = []
        old_doc = doc.get_doc_before_save()

        if old_doc:
            for field in doc.meta.fields:
                fieldname = field.fieldname

                if field.fieldtype == "Table":
                    old_rows = old_doc.get(fieldname) or []
                    new_rows = doc.get(fieldname) or []

                    if len(old_rows) != len(new_rows):
                        changed_fields.append(field.label or fieldname)
                        continue

                    child_meta = frappe.get_meta(field.options)
                    row_changed = False

                    for old_row, new_row in zip(old_rows, new_rows):
                        for child_field in child_meta.fields:
                            cfn = child_field.fieldname
                            if old_row.get(cfn) != new_row.get(cfn):
                                row_changed = True
                                break
                        if row_changed:
                            break

                    if row_changed:
                        changed_fields.append(field.label or fieldname)
                else:
                    if doc.get(fieldname) != old_doc.get(fieldname):
                        changed_fields.append(field.label or fieldname)

        if changed_fields:
            subject_text = doc.employee_name + " updated: " + ", ".join(changed_fields)

            hr_user_rows = frappe.db.sql("""
                SELECT u.name
                FROM `tabUser` u
                JOIN `tabHas Role` hr ON hr.parent = u.name
                WHERE hr.role IN ('HR Manager', 'HR User')
                AND u.enabled = 1
            """, as_dict=True)

            unique_users = list(set([r.name for r in hr_user_rows]))

            for user_email in unique_users:
                frappe.get_doc({
                    "doctype": "Notification Log",
                    "for_user": user_email,
                    "from_user": frappe.session.user,
                    "subject": subject_text,
                    "type": "Alert",
                    "document_type": "Employee",
                    "document_name": doc.name
                }).insert(ignore_permissions=True)

# Generalized tracking script for Job Applicant stage
job_applicant_name = None
if doc.doctype == "Job Applicant":
    job_applicant_name = doc.name
elif doc.get("job_applicant"):
    job_applicant_name = doc.job_applicant

if job_applicant_name:
    stage = "Applied"

    # 1. Check Appointment Letter
    appt_letter = frappe.get_all("Appointment Letter", filters={"job_applicant": job_applicant_name, "docstatus": ("<", 2)}, limit=1)
    if appt_letter:
        stage = "Appointment Letter Issued"
    else:
        # 2. Check Job Offer
        job_offer = frappe.get_all("Job Offer", filters={"job_applicant": job_applicant_name, "docstatus": ("<", 2)}, fields=["status"], limit=1)
        if job_offer:
            offer_status = job_offer[0].status
            if offer_status == "Awaiting Response" or not offer_status:
                stage = "Offer Issued"
            elif offer_status == "Accepted":
                stage = "Offer Accepted"
            elif offer_status == "Rejected":
                stage = "Offer Rejected"
            else:
                stage = f"Offer {offer_status}"
        else:
            # 3. Check Interview
            latest_interview = frappe.get_all(
                "Interview",
                filters={"job_applicant": job_applicant_name, "docstatus": ("<", 2)},
                fields=["interview_type", "status", "scheduled_on"],
                order_by="scheduled_on desc, creation desc",
                limit=1
            )
            if latest_interview:
                iv = latest_interview[0]
                round_name = iv.interview_type or "Interview"
                if iv.status == "Pending":
                    stage = f"{round_name} Scheduled"
                elif iv.status == "Cleared":
                    stage = f"{round_name} Cleared"
                elif iv.status == "Rejected":
                    stage = f"{round_name} Rejected"
                else:
                    stage = f"{round_name} - {iv.status}"

    frappe.db.set_value("Job Applicant", job_applicant_name, "custom_current_stage", stage)

